def normalise_order(raw: dict) -> dict:
    # Validate required keys
    for key in ["sku", "qty", "unit_price_pence"]:
        if key not in raw:
            raise ValueError(f"Missing required key: {key}")

    # Process SKU
    sku = raw["sku"]
    if not isinstance(sku, str):
        raise ValueError("SKU must be a string")
    sku = sku.strip().upper()
    if not sku:
        raise ValueError("SKU cannot be empty after stripping")

    # Process Qty
    qty_raw = raw["qty"]
    try:
        qty = int(qty_raw)
    except (ValueError, TypeError):
        raise ValueError(f"Invalid qty value: {qty_raw}")

    if not (1 <= qty <= 99):
        raise ValueError(f"Qty must be between 1 and 99 inclusive, got {qty}")

    # Process Unit Price
    price_raw = raw["unit_price_pence"]
    try:
        unit_price_pence = int(price_raw)
    except (ValueError, TypeError):
        raise ValueError(f"Invalid unit_price_pence value: {price_raw}")

    if unit_price_pence < 0:
        raise ValueError("Unit price pence must be 0 or more")

    # Process Currency
    currency = raw.get("currency", "")
    if not isinstance(currency, str):
        currency = ""
    currency = currency.strip().upper()

    allowed_currencies = {"GBP", "EUR", "USD"}
    if currency in ("", None):
        currency = "GBP"
    elif currency not in allowed_currencies:
        raise ValueError(f"Invalid currency: {currency}")

    # Calculate Total
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence
    }
