import re
from datetime import date
from calendar import monthrange

def parse_date(text: str) -> date:
    """
    Parses a date string from three specific formats:
    1. ISO: YYYY-MM-DD
    2. British numeric: DD/MM/YYYY
    3. Short text: D Mon YYYY (e.g., 7 Mar 2025)

    Raises ValueError for invalid formats or impossible dates.
    """
    text = text.strip()
    if not text:
        raise ValueError("Empty input")

    # Pattern 1: ISO (YYYY-MM-DD)
    iso_pattern = r'^(\d{4})-(\d{2})-(\d{2})$'
    match = re.match(iso_pattern, text)
    if match:
        try:
            year, month, day = int(match.group(1)), int(match.group(2)), int(match.group(3))
            return date(year, month, day)
        except ValueError:
            raise ValueError("Invalid ISO date components")

    # Pattern 2: British Numeric (DD/MM/YYYY)
    brit_pattern = r'^(\d{1,2})/(\d{1,2})/(\d{4})$'
    match = re.match(brit_pattern, text)
    if match:
        try:
            day, month, year = int(match.group(1)), int(match.group(2)), int(match.group(3))
            return date(year, month, day)
        except ValueError:
            raise ValueError("Invalid British numeric date components")

    # Pattern 3: Short text (D Mon YYYY)
    # Month names are case-insensitive, but we expect standard English abbreviations
    short_pattern = r'^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$'
    match = re.match(short_pattern, text)
    if match:
        day_str, month_str, year_str = match.groups()
        try:
            year = int(year_str)
            # Map 3-letter month to index (1-12)
            months = {
                'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
                'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
            }
            month = months.get(month_str.lower())
            if not month:
                raise ValueError(f"Unknown month: {month_str}")

            day = int(day_str)
            # Validate the date is actually possible (e.g., no Feb 30)
            max_day = monthrange(year, month)[1]
            if day > max_day:
                raise ValueError(f"Day {day} is not valid for {month_str} {year}")

            return date(year, month, day)
        except (ValueError, KeyError):
            raise ValueError("Invalid short text date components")

    raise ValueError(f"Unrecognized date format: '{text}'")
```

The function handles three distinct formats by attempting regex matches in order of specificity. It uses `re` for pattern matching and `calendar.monthrange` to validate that the day exists within the specific month and year (handling leap years automatically). Any input failing these checks or containing impossible dates raises a `ValueError`.

