function parseQuery(qs) {
  if (typeof qs !== 'string') return {};

  // Remove leading '?' if present
  const raw = qs.startsWith('?') ? qs.slice(1) : qs;

  // Split by '&' and filter out empty strings (handles trailing && or just &)
  const pairs = raw.split('&').filter(pair => pair.length > 0);

  const result = {};

  for (const pair of pairs) {
    // Split only on the FIRST '='
    const index = pair.indexOf('=');

    if (index === -1) {
      // Key without value -> empty string
      const key = decodeURIComponent(pair.replace(/+/g, ' '));
      if (!result[key]) result[key] = "";
      else result[key] = [result[key]];
      continue;
    }

    const keyRaw = pair.slice(0, index);
    const valueRaw = pair.slice(index + 1);

    // Decode: replace '+' with space, then percent-decode
    const key = decodeURIComponent(keyRaw.replace(/+/g, ' '));
    const value = decodeURIComponent(valueRaw.replace(/+/g, ' '));

    if (!result[key]) {
      result[key] = value;
    } else {
      // Convert existing string to array and push new value
      if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        result[key] = [result[key], value];
      }
    }
  }

  return result;
}
```

This function manually parses the query string by splitting on `&`, then finding the first `=` to separate keys and values. It handles decoding (`+` as space, then `decodeURIComponent`) and manages duplicate keys by storing them in arrays, while skipping empty pairs automatically via filtering.

