function deepMerge(base, override) {
  if (typeof base !== 'object' || base === null || typeof override !== 'object' || override === null) {
    // If either is not a plain object (or is null), return the override value.
    // Note: null is treated as a replacement per requirements, but since it's not a plain object,
    // the recursive merge won't happen, effectively replacing base with null if that was intended.
    // However, to strictly follow "plain objects" logic for recursion and "null replaces",
    // we check if both are plain objects first.
    return override;
  }

  // Ensure we don't modify the original objects by creating shallow copies of the top-level inputs
  // if they happen to be arrays or null, though the recursive logic handles nested structures.
  // The requirement "Never modify base or override" implies we must not mutate them.
  // Since we are only reading and constructing a new object, standard property access is safe.
  // We just need to ensure we don't assign directly to existing properties of base/override.

  const result = {};

  // Get all keys from both objects to handle keys present in either
  const allKeys = new Set([...Object.keys(base), ...Object.keys(override)]);

  for (const key of allKeys) {
    const baseVal = base[key];
    const overrideVal = override[key];

    // If the key exists in override and its value is not undefined, process it.
    if (overrideVal !== undefined) {
      // Check if both values are plain objects (not arrays, not null)
      if (typeof baseVal === 'object' && baseVal !== null && !Array.isArray(baseVal) &&
          typeof overrideVal === 'object' && overrideVal !== null && !Array.isArray(overrideVal)) {
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        // Override replaces the base value (including arrays and null)
        result[key] = overrideVal;
      }
    } else {
      // undefined in override means keep the base value
      if (baseVal !== undefined) {
        result[key] = baseVal;
      }
    }
  }

  return result;
}
```

The function recursively merges two configuration objects. It creates a new object at every step to ensure immutability of the inputs and all nested structures. If both values at a specific key are plain objects, they are merged recursively; otherwise, the `override` value completely replaces the `base` value (including arrays and `null`). Keys unique to `base` are preserved unless explicitly overridden or set to `undefined`.

