long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total_seconds = 0;
    int hours = 0, minutes = 0, seconds_part = 0;
    bool h_seen = false, m_seen = false, s_seen = false;
    size_t i = 0;

    while (i < s.size()) {
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) {
            // Check for space or invalid character
            if (s[i] == ' ') return -1;
            return -1;
        }

        // Parse number
        size_t start = i;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
            ++i;
        }

        if (start == i) return -1; // Number without unit

        long long num = 0;
        for (size_t j = start; j < i; ++j) {
            num = num * 10 + (s[j] - '0');
        }

        // Check unit
        if (i >= s.size()) return -1; // Unit without number (handled by next check implicitly)

        char unit = s[i];
        ++i;

        if (unit == 'h') {
            if (h_seen) return -1; // Repeated unit
            h_seen = true;
            if (m_seen || s_seen) return -1; // Wrong order (must be h, then m, then s)
            hours = num;
        } else if (unit == 'm') {
            if (m_seen) return -1; // Repeated unit
            m_seen = true;
            if (!h_seen) return -1; // Wrong order
            if (s_seen) return -1; // Wrong order (must be h, then m, then s)
            minutes = num;
        } else if (unit == 's') {
            if (s_seen) return -1; // Repeated unit
            s_seen = true;
            if (!h_seen && !m_seen) return -1; // Wrong order
            seconds_part = num;
        } else {
            return -1; // Unknown unit
        }
    }

    // If string is not empty but we didn't parse any valid component (e.g., just "abc")
    if (!h_seen && !m_seen && !s_seen) return -1;

    total_seconds = hours * 3600LL + minutes * 60LL + seconds_part;
    return total_seconds;
}
```

This function parses strings like `1h30m` or `45s` by iterating through the input, extracting numbers and their associated units (`h`, `m`, `s`). It enforces strict rules: units must appear in order (hours first, then minutes, then seconds), each unit can only appear once, there must be a number before every unit, no spaces are allowed, and unknown characters result in an error. If all checks pass, it calculates the total seconds; otherwise, it returns `-1`.

