def parse_date(text: str) -> datetime.date:
    """
    Parses a date string accepting three specific formats:
    - ISO: YYYY-MM-DD
    - British numeric: DD/MM/YYYY
    - Short text: D Mon YYYY

    Raises ValueError for any other format or impossible date.
    """
    text = text.strip()

