    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", text):
        try:
            return datetime.datetime.strptime(text, "%Y-%m-%d").date()
        except ValueError:
            # This should technically not happen if the regex matches,
            # but included for robustness against leap year checks in strptime
            raise ValueError("Invalid date components provided.")

    # 2. British Numeric Format: 07/03/2025
    elif re.fullmatch(r"\d{2}/\d{2}/\d{4}", text):
        try:
            # Day/Month/Year
            return datetime.datetime.strptime(text, "%d/%m/%Y").date()
        except ValueError:
            raise ValueError("Invalid date components provided.")

    # 3. Short Text Format: 7 Mar 2025 (or 07 Mar 2025)
    elif re.fullmatch(r"\d{1,2} [A-Za-z]{3} \d{4}", text):
        # We use strptime with %b for abbreviated month names.
        # It is case-insensitive for month names generally, but strptime prefers Title Case.
        # We test a standardized format: Day Month Year
        try:
            # Python's strptime can handle leading zeros if necessary, but it's safer
            # to let it parse the given structure.
            return datetime.datetime.strptime(text, "%d %b %Y").date()
        except ValueError:
            # If the simple structure fails, it might be due to locale or structure,
            # but if the regex passed, this error means the date itself is invalid (e.g., 32 Feb 2025)
            raise ValueError("Invalid date components provided.")

    else:
        raise ValueError(f"Date format not supported. Must be YYYY-MM-DD, DD/MM/YYYY, or D Mon YYYY.")

