def normalise_order(raw: dict) -> dict:
    """
    Normalises a raw order dictionary received from a web form into a standardised format.

    Args:
        raw: A dictionary containing raw order data.

    Returns:
        A new dictionary with the keys: sku, qty, unit_price_pence, currency, total_pence.

    Raises:
        ValueError: If required fields are missing or values are invalid.
    """
    # 1. SKU Normalisation
    if "sku" not in raw:
        raise ValueError("Missing required key: 'sku'")
    sku = raw["sku"].strip().upper()
    if not sku:
        raise ValueError("SKU cannot be empty after stripping.")

    # 2. Quantity Normalisation
    try:
        # Handles int or string representation of integer
        qty_raw = raw["qty"]
        if isinstance(qty_raw, str):
            qty = int(float(qty_raw.strip())) # Use float conversion first to handle "3.0" like strings if necessary, though int() should suffice for standard clean input
            qty = int(qty)
        elif isinstance(qty_raw, int):
            qty = qty_raw
        else:
            raise TypeError("Quantity must be an integer or string.")

        if not (1 <= qty <= 99):
            raise ValueError(f"Quantity must be between 1 and 99, got {qty}.")

    except (ValueError, TypeError) as e:
        # Catch issues during int conversion or boundary checks
        raise ValueError(f"Invalid quantity format or value: {e}")


    # 3. Unit Price Normalisation
    if "unit_price_pence" not in raw:
        raise ValueError("Missing required key: 'unit_price_pence'")
    try:
        unit_price_pence = int(raw["unit_price_pence"])
        if unit_price_pence < 0:
            raise ValueError("Unit price must be non-negative.")
    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid unit_price_pence format or value: {e}")

    # 4. Currency Normalisation
    currency = raw.get("currency")
    if currency is None:
        currency_str = "GBP"
    else:
        currency_str = str(currency).strip().upper()

    allowed_currencies = {"GBP", "EUR", "USD"}
    if not currency_str or currency_str not in allowed_currencies:
        currency = "GBP" if currency_str in ("NONE", "") else currency_str
        if currency not in allowed_currencies:
             # Re-evaluate the "None" or blank case explicitly for the allowed set
             if currency_str == "":
                 currency = "GBP"
             elif currency_str.upper() in ("NONE", ""):
                 currency = "GBP"
             elif currency_str.upper() in allowed_currencies:
                 currency = currency_str.upper()
             else:
                 # If it was explicitly set but invalid (and not "" or NONE)
                 raise ValueError(f"Unsupported currency: {raw.get('currency')}")
        else:
            currency = currency_str


    # 5. Total Pence Calculation
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence
    }

