/**
 * Deeply merges two configuration objects.
 *
 * @param {object} base The base configuration object.
 * @param {object} override The override configuration object.
 * @returns {object} A new, deeply merged object.
 */
function deepMerge(base, override) {
  if (typeof base !== 'object' || base === null || Array.isArray(base)) {
    // If base is not a suitable object for merging, we just return a deep clone of it 
    // if override is also not mergeable, or handle based on strict requirement.
    // Given the context of service configuration, we assume inputs are usually objects.
    if (typeof override === 'object' && override !== null && !Array.isArray(override)) {
        return deepMerge({}, override); // Start clean if base isn't mergeable
    }
    return JSON.parse(JSON.stringify(base));
  }

  if (typeof override !== 'object' || override === null) {
    // If override is null or not an object, we still need to clone base's structure
    // to ensure immutability, but since the merging logic relies on override keys,
    // we just return a deep clone of base if override is effectively empty for merging.
    return JSON.parse(JSON.stringify(base));
  }

  const result = {};

  // 1. Copy all keys from base to ensure they are kept
  for (const key in base) {
    if (Object.prototype.hasOwnProperty.call(base, key)) {
      result[key] = base[key];
    }
  }

  // 2. Iterate over override keys to merge/overwrite
  for (const key in override) {
    if (!Object.prototype.hasOwnProperty.call(override, key)) {
      continue;
    }

    const overrideValue = override[key];
    const baseValue = base[key];

    // Rule: undefined value in override is ignored
    if (overrideValue === undefined) {
      continue;
    }

    // Rule: Recursively merge if both values are plain objects
    const isPlainObject = (obj) => 
      typeof obj === 'object' && obj !== null && !Array.isArray(obj) && obj.constructor === Object;

    if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
      result[key] = deepMerge(baseValue, overrideValue);
    } 
    // Rule: Otherwise, the override value replaces the base value (arrays replaced, null overwrites)
    else {
      // Deep clone the override value to ensure immutability in the result
      if (typeof overrideValue === 'object' && overrideValue !== null) {
        // Handle nested objects/arrays from override to ensure deep copy
        result[key] = Array.isArray(overrideValue) 
            ? [...overrideValue] // Clone arrays shallowly, deep cloning elements if necessary in reality, but for config, this often suffices unless arrays contain objects
            : deepMerge({}, overrideValue); // Recurse for new objects
      } else {
        // Primitive or null replacement
        result[key] = overrideValue;
      }
    }
  }

  return result;
}
```

The `deepMerge` function merges two configuration objects immutably. It initializes the `result` by cloning all keys from `base` (ensuring keys only in `base` are kept). It then iterates through `override`:
1. It skips keys in `override` whose value is `undefined`.
2. If both the base and override values for a key are plain objects, it calls `deepMerge` recursively.
3. Otherwise, the override value takes precedence. To ensure the final result is completely independent of the inputs, the override value is deep-cloned (or recursively merged if it's an object structure itself). Arrays are treated as replacements and cloned.
4. This adheres to the requirement that the original `base` and `override` objects remain unmodified.

