long long parse_duration(const std::string& s) {
    if (s.empty()) {
        return -1;
    }

    long long total_seconds = 0;
    int current_pos = 0;

    // Keep track of encountered units to detect duplicates and enforce order
    bool found_h = false;
    bool found_m = false;
    bool found_s = false;

    while (current_pos < s.length()) {
        size_t start_num = current_pos;

        // 1. Parse the number part (must be digits)
        while (current_pos < s.length() && std::isdigit(s[current_pos])) {
            current_pos++;
        }

        if (current_pos == start_num) {
            // No digits found where expected (must start with a number)
            return -1;
        }

        std::string num_str = s.substr(start_num, current_pos - start_num);
        long long value = std::stoll(num_str);

        // 2. Check for the unit part
        if (current_pos >= s.length()) {
            // Reached end of string after digits but no unit
            return -1;
        }

        char unit_char = s[current_pos];
        current_pos++;

        int multiplier = 0;
        bool valid_unit = true;

        if (unit_char == 'h') {
            if (found_h) return -1; // Repeated unit
            multiplier = 3600;
            found_h = true;
        } else if (unit_char == 'm') {
            if (found_m) return -1; // Repeated unit
            multiplier = 60;
            found_m = true;
        } else if (unit_char == 's') {
            if (found_s) return -1; // Repeated unit
            multiplier = 1;
            found_s = true;
        } else {
            // Unknown unit character
            return -1;
        }

        // Enforce order check: H -> M -> S
        if (unit_char == 'm' && found_h == false) return -1;
        if (unit_char == 's') {
            if (found_m && !found_h) return -1; // 's' appeared before 'm' (unless 'h' was also skipped)
            if (found_m && found_s) return -1; // Should be caught by found_s check, but for clarity
        }

        // A more robust order check might be needed, but based on the strict H, M, S order:
        // If we see 'm' but haven't seen 'h', it's invalid.
        // If we see 's' but haven't seen 'h' or 'm' (and thus we can't guarantee H/M precedence unless we track indices),
        // let's rely on the flags and the fact that we must progress through H then M then S.

        // Since we traverse the string linearly, checking the flags is the most straightforward way 
        // to enforce that we only use the next valid unit in sequence *if* the previous one was used.
        // However, the requirement says "Units must appear in the order h, m, s, each at most once".
        // This implies that if we see 'm', 'h' MUST have been seen already OR 'h' must be skipped entirely if 'm' is first (which is illegal).

        // Let's re-check the order strictly:
        // If we see 'm' and 'h' hasn't been seen, it's an error.
        if (unit_char == 'm' && !found_h && !found_m) {
             // If this is the first unit, it must be 'h' or 's' (if 'h' is skipped, but 'm' must follow 'h')
             // The only valid starts are 'h' or 's' (if we allow skipping H, but the spec implies sequence H->M->S)
             // A simple check: if we see M, H must have happened.
             if (!found_h) return -1;
        }
        // If we see 's' and 'h' or 'm' wasn't properly established first
        if (unit_char == 's' && (!found_h && !found_m) && (found_h != found_m)) {
             // This condition is tricky. We assume H, M, S implies that if we see 's', we must have passed the valid path through H and M.
             // Since we are parsing segment by segment, we check if the sequence is broken.
             // If we see 's', and either 'h' or 'm' was skipped when they were expected before 's', it's an error.
             // The simplest strict interpretation: units must appear H -> M -> S
             if (!found_m && found_h == false) { // If H wasn't seen, M can't be seen, S can't be seen unless S is first (which is wrong).
                // The structure implies the state machine: Start -> H -> M -> S -> End.
                // If we hit 's' but 'm' was never seen, it's invalid unless H was also never seen and S is the start (but that violates H->M->S).
                if (!found_m) return -1;
             }
        }


        total_seconds += value * multiplier;
    }

    return total_seconds;
}
