long long parse_duration(const std::string& s) {
    std::unordered_map<char, int> unit_map = {{'h', 3600}, {'m', 60}, {'s', 1}};
    long long total_seconds = 0;
    int current_number = 0;
    char current_unit = '\0';
    bool is_negative = false;
    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (isdigit(c)) {
            current_number = current_number * 10 + (c - '0');
        } else if (c == '-') {
            is_negative = true;
        } else if (unit_map.find(c) != unit_map.end()) {
            if (current_unit != '\0' && unit_map.find(current_unit) != unit_map.end()) {
                return -1;
            }
            current_unit = c;
        } else {
            return -1;
        }
        if (i == s.length() - 1 || !isdigit(c) && c != current_unit) {
            if (current_unit == '\0') return -1;
            total_seconds += current_number * unit_map[current_unit];
            current_number = 0;
            current_unit = '\0';
        }
    }
    if (current_unit != '\0') return -1;
    return is_negative ? -total_seconds : total_seconds;
}
