from datetime import date
import re

def parse_date(text: str) -> date:
    """
    Parses invoice dates in three formats:
      - ISO: '2025-03-07'
      - British numeric: '07/03/2025' (day/month/year)
      - Short text: '7 Mar 2025' (English month name, optional leading zero on day)

    Raises ValueError for invalid formats or impossible dates.
    """
    # Strip surrounding whitespace
    s = text.strip()

    if not s:
        raise ValueError("Empty date string")

    # Try ISO format: YYYY-MM-DD
    m1 = re.match(r'^\d{4}-\d{2}-\d{2}$', s)
    if m1:
        try:
            return date(int(m1.group(1)), int(m1.group(2)), int(m1.group(3)))
        except ValueError:
            pass

    # Try British numeric: DD/MM/YYYY
    m2 = re.match(r'^\d{2}/\d{2}/\d{4}$', s)
    if m2:
        try:
            return date(int(m2.group(1)), int(m2.group(2)), int(m2.group(3)))
        except ValueError:
            pass

    # Try Short text: D Month YYYY (with optional leading zero on day)
    m3 = re.match(r'^\d{1,2}\s+(\w+)\s+\d{4}$', s)
    if m3:
        day_str = m3.group(1).lstrip('0')  # Remove leading zero if present
        month_name = m3.group(2).lower()

        if month_name == 'jan':
            month = 1
        elif month_name == 'feb':
            month = 2
        elif month_name == 'mar':
            month = 3
        elif month_name == 'apr':
            month = 4
        elif month_name == 'may':
            month = 5
        elif month_name == 'jun':
            month = 6
        elif month_name == 'jul':
            month = 7
        elif month_name == 'aug':
            month = 8
        elif month_name == 'sep':
            month = 9
        elif month_name == 'oct':
            month = 10
        elif month_name == 'nov':
            month = 11
        elif month_name == 'dec':
            month = 12
        else:
            raise ValueError(f"Unknown month name: {month_name}")

        try:
            return date(int(day_str), month, int(m3.group(4)))
        except ValueError:
            pass

    # If none match, raise error
    raise ValueError(f"Invalid date format: {text}")
