import re

def normalise_order(raw: dict) -> dict:
    """
    Normalizes a raw order dict into a valid checkout format.
    Raises ValueError if any validation fails or required fields are missing.
    """
    # Extract and normalize sku
    sku_str = str(raw.get("sku"))
    sku_upper = sku_str.strip().upper()
    if not sku_upper:
        raise ValueError("SKU cannot be empty after stripping.")

    # Extract and normalize qty
    qty_raw = raw.get("qty")
    if isinstance(qty_raw, str):
        try:
            qty_int = int(qty_raw)
        except ValueError:
            raise ValueError(f"Invalid qty value: {qty_raw}")
    else:
        qty_int = int(qty_raw)

    if qty_int < 1 or qty_int > 99:
        raise ValueError("Qty must be between 1 and 99.")

    # Extract and normalize unit_price_pence
    price_raw = raw.get("unit_price_pence")
    if isinstance(price_raw, str):
        try:
            price_int = int(price_raw)
        except ValueError:
            raise ValueError(f"Invalid unit_price_pence value: {price_raw}")
    else:
        price_int = int(price_raw)

    # Validate currency
    currency_raw = raw.get("currency")
    if currency_raw is not None and isinstance(currency_raw, str):
        currency_upper = currency_raw.strip().upper()
        if currency_upper in ("GBP", "EUR", "USD"):
            currency = currency_upper
        else:
            raise ValueError(f"Invalid currency: {currency_raw}")
    elif raw.get("currency") is None or raw.get("currency") == "" or not isinstance(raw.get("currency"), str):
        # If currency is missing, None, empty string, or not a string -> use default
        currency = "GBP"  # Fallback as per spec: if missing/blank/invalid, treat as GBP
    else:
        raise ValueError(f"Invalid currency value: {raw.get('currency')}")

    # Calculate total
    total_pence = qty_int * price_int

    return {
        "sku": sku_upper,
        "qty": qty_int,
        "unit_price_pence": price_int,
        "currency": currency,
        "total_pence": total_pence
    }
```

