function deepMerge(base, override) {
  if (override === undefined || override === null) {
    return base;
  }

  const result = {};

  for (const key of Object.keys(override)) {
    const overrideVal = override[key];
    const baseVal = base[key];

    // If both are plain objects, recurse deeply
    if (baseVal && typeof baseVal === 'object' && Array.isArray(baseVal) === false) {
      result[key] = deepMerge(baseVal, overrideVal);
    } else if (overrideVal !== undefined && overrideVal !== null) {
      // Override replaces the base value entirely for non-object types
      result[key] = overrideVal;
    } else {
      // If key exists only in base, keep it as is
      result[key] = baseVal;
    }
  }

  return result;
}
