function parseQuery(qs) {
  const result = {};

  // Remove leading '?' if present, then split by '&'
  const pairs = (qs || '').replace(/^\?/, '').split('&');

  for (const pair of pairs) {
    // Skip empty strings (from && or trailing &)
    if (!pair.trim()) continue;

    const eqIndex = pair.indexOf('=');

    // If no '=', key is the whole string, value is empty
    const key = eqIndex === -1 ? pair : pair.substring(0, eqIndex);
    const value = eqIndex === -1 ? "" : decodeURIComponent(pair.substring(eqIndex + 1).replace(/\+/g, ' '));

    // Decode the key as well (replace + with space then percent-decode)
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));

    if (!result.hasOwnProperty(decodedKey)) {
      result[decodedKey] = value;
    } else {
      if (Array.isArray(result[decodedKey])) {
        result[decodedKey].push(value);
      } else {
        result[decodedKey] = [result[decodedKey], value];
      }
    }
  }

  return result;
}
```

