        d, m, y = map(int, text.split("/"))
        if 1 <= d <= 31 and 1 <= m <= 12 and 1 <= y <= 9999:
            return date(y, m, d)
    except (ValueError, TypeError):
        pass

    # Try short text: D MMM YYYY
    try:
        parts = text.split()
        if len(parts) != 3:
            raise ValueError(f"Expected three parts for 'D MMM YYYY', got {len(parts)}")
        day_str, month_str, year_str = parts
        day = int(day_str)
        year = int(year_str)
        months = {
            "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
            "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
        }
        month = months.get(month_str.lower())
        if month is not None and 1 <= day <= 31 and 1 <= year <= 9999:
            return date(year, month, day)
    except (ValueError, TypeError):
        pass

    raise ValueError(f"Unable to parse date: {text}")
```

**Explanation:** The function strips whitespace, then attempts parsing in three order of precedence: ISO format first, then British numeric (`DD/MM/YYYY`), then short text (`D MMM YYYY`). It validates ranges for day/month/year and raises `ValueError` for any invalid input or impossible dates.

