function parseQuery(qs) {
  const result = {};

  // Skip leading '?'
  if (qs && qs[0] === '?') {
    qs = qs.slice(1);
  }

  // Split pairs by '&'
  if (!qs || qs.trim() === '') return {};

  const parts = qs.split('&');

  for (const part of parts) {
    if (!part) continue; // skip empty pairs from '&&' or trailing '&'

    const eqIndex = part.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = decodeURIComponent(decodePart(part));
      value = '';
    } else {
      key = decodeURIComponent(decodePart(part.slice(0, eqIndex)));
      value = decodeURIComponent(decodePart(part.slice(eqIndex + 1)));
    }

    if (key === '') continue; // skip empty keys

    if (result[key] !== undefined) {
      result[key].push(value);
    } else {
      result[key] = value;
    }
  }

  return result;
}

function decodePart(str) {
  const out = '';
  let i = 0;
  while (i < str.length) {
    if (str[i] === '%' && i + 2 < str.length) {
      const hex = str.slice(i + 1, i + 3);
      out += String.fromCharCode(parseInt(hex, 16));
      i += 3;
    } else {
      out += str[i];
      i++;
    }
  }
  return out;
}
```

Brief explanation: The function splits the query string on `&`, skips empty pairs, decodes `+` as spaces and percent-encoding via a custom decoder, and uses an object to store single values or arrays for repeated keys.

```javascript
function deepMerge(base, override) {
  if (override === undefined || override === null) return base;
  if (typeof base !== "object" || typeof override !== "object") return override;
  if (Array.isArray(override)) return [...override];
  if (Array.isArray(base)) return [...base];

  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = deepMerge(base[key], override[key]);
  }
  for (const key of Object.keys(override)) {
    result[key] = deepMerge(base[key], override[key]);
  }
  return result;
}
```

The function returns a new object that recursively merges `base` and `override`. For plain objects, it recurses into nested keys; for arrays, it replaces with a shallow copy. `undefined` values in `override` are skipped (base is preserved), while `null` overrides the base value. Keys unique to `base` or `unique to `override` are included in the result.

