class Paginator:
    """Splits a list of search results into 1-based pages."""

    def __init__(self, items: list, page_size: int):
        if page_size < 1:
            raise ValueError("page_size must be >= 1")
        self.items = items
        self.page_size = page_size

    @property
    def page_count(self) -> int:
        return len(self.items) // self.page_size

    def get_page(self, number: int) -> Page:
