import datetime

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string accepted in ISO, British numeric, or short text format.
    """
    text = text.strip()

    # Attempt ISO format: 2025-03-07
    try:
        return datetime.datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Attempt British numeric format: 07/03/2025 (day/month/year)
    try:
        return datetime.datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # Attempt Short text format: 7 Mar 2025
    # We need to handle both '7 Mar 2025' and '07 Mar 2025'
    try:
        # %d handles both single and double digit days correctly
        return datetime.datetime.strptime(text, "%d %b %Y").date()
    except ValueError:
        pass

    raise ValueError(f"Date string '{text}' does not match ISO, British numeric, or short text format.")

# Example usage (for testing purposes, not part of the required function definition)
if __name__ == '__main__':
    try:
        print(parse_date("2025-03-07"))  # ISO
        print(parse_date(" 07/03/2025 ")) # British Numeric
        print(parse_date("7 Mar 2025"))  # Short Text (no leading zero)
        print(parse_date("07 Mar 2025")) # Short Text (with leading zero)

        # This should fail:
        # print(parse_date("2025-02-30")) 
        # print(parse_date("31/02/2025")) 
    except ValueError as e:
        print(f"Error: {e}")

    try:
        parse_date("2025-03-07T10:00")
    except ValueError as e:
        print(f"Error: {e}")
```

This implementation uses three sequential `try...except` blocks to attempt parsing the input against the specified formats using `datetime.datetime.strptime`:
1. `%Y-%m-%d` for ISO format.
2. `%d/%m/%Y` for British numeric (DD/MM/YYYY).
3. `%d %b %Y` for the short text format, where `%b` automatically handles three-letter English month abbreviations (like 'Mar').

If all parsing attempts fail (e.g., due to invalid characters, wrong order, or impossible dates like 31/02/2025 which `strptime` validates), it raises a `ValueError`. Leading/trailing whitespace is handled by `text.strip()`.

