long long parse_duration(const std::string& s) {
    if (s.empty()) {
        return -1;
    }

    // Regex to capture parts: (digits)(unit)
    // It ensures that the string is composed entirely of these parts.
    // The pattern allows for h, m, or s, and checks for the correct sequence implicitly
    // by how we process the matches later.
    // It also inherently disallows spaces and signs because they are not in the allowed characters.
    std::regex part_regex("([0-9]+)([HMS])");
    auto words_begin = std::sregex_iterator(s.begin(), s.end(), part_regex);
    auto words_end = std::sregex_iterator();

    std::vector<std::string> matched_parts;
    for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
        std::smatch match = *i;
        matched_parts.push_back(match.str(0));
    }

    // Check if the regex matched the entire string. If matched_parts.size() * avg_part_length < s.length(), 
    // there are characters that did not match the pattern (like spaces or misplaced characters).
    if (matched_parts.empty() && !s.empty()) {
        // If there are no matches but the string is not empty, it's invalid (e.g., "abc", "123", "h")
        return -1;
    }

    // Reconstruct the string from matches and check if it matches the original string exactly
    std::string reassembled_s;
    for (const auto& part : matched_parts) {
        reassembled_s += part;
    }
    if (reassembled_s != s) {
        // This catches cases where the regex found parts but left garbage (like spaces, signs, or extra characters)
        return -1;
    }

    long long total_seconds = 0;
    // Track seen units to ensure no repeats and to enforce order H -> M -> S
    bool seen_h = false;
    bool seen_m = false;
    bool seen_s = false;

    for (const auto& part : matched_parts) {
        // Part format: "numberUnit" (e.g., "1h", "30m")
