            seen_h = true;
        } else if (unit == 'm') {
            if (seen_m || seen_h == false || seen_s) return -1; // Repeat or wrong order (must follow H, or be first if H wasn't specified)
            // We only check for H if H *was* specified, but the strict order is H must precede M.
            if (seen_h == false && seen_s == true) return -1; // M after S (impossible given the loop structure unless S came first)
            seen_m = true;
        } else if (unit == 's') {
