                } else if (seen_h && !seen_m) {
                    // Valid state: H then S (M omitted)
                } else if (!seen_h && seen_m) {
                    // Invalid: M before H (This case is implicitly handled by the logic below, but let's simplify the check)
                    // If we see S, we must have seen H and M in correct order, OR just H, OR just M.
                    // The strict requirement is H -> M -> S, each AT MOST once.
                    // If we see 's', it must be preceded by at most 'm', and 'm' by at most 'h'.
                    return -1; // If S is encountered, but the prerequisite sequence isn't met
                } else if (!seen_h && !seen_m) {
