                }
            }
            seen_s = true;
        } else {
            // Unknown unit (should be caught by regex but kept for robustness)
            return -1;
        }

        // Recalculate units/order based on seen flags after adding the new unit
        // This simplifies the complex flow control above.
        bool order_ok = true;
        if (seen_h && (unit == 'm' && !seen_h) || (unit == 's' && (!seen_h && !seen_m))) order_ok = false;
        if (seen_m && (unit == 's' && !seen_m)) order_ok = false; // This check is redundant with the above but confirms M precedes S
