/**
 * Parses a query string into an object.
 * @param {string} qs - The query string (with or without leading '?').
 * @returns {Object.<string, (string|string[])>} The parsed query parameters.
 */
function parseQuery(qs) {
    const params = {};
    if (!qs) return params;

    // 1. Remove leading '?' if present
    const queryString = qs.startsWith('?') ? qs.slice(1) : qs;

    if (!queryString) return params;

    // 2. Split into key=value pairs, skipping empty ones
    const pairs = queryString.split('&).filter(pair => pair.length > 0);

    for (const pair of pairs) {
        const eqIndex = pair.indexOf('=');
        let key, value;

        if (eqIndex === -1) {
            key = pair;
            value = "";
        } else {
            key = pair.substring(0, eqIndex);
            value = pair.substring(eqIndex + 1);
        }

        // Handle '+' as space substitution
        key = key.replace(/\+/g, ' ');
        value = value.replace(/\+/g, ' ');

        // Decode keys and values
        try {
            key = decodeURIComponent(key);
            value = decodeURIComponent(value);
        } catch (e) {
            // If decoding fails, keep the raw string (or handle error as needed)
        }

        if (key) {
            if (Object.prototype.hasOwnProperty.call(params, key)) {
                // Key exists, convert to array if it wasn't one already
                if (Array.isArray(params[key])) {
                    params[key].push(value);
                } else {
                    params[key] = [params[key], value];
                }
            } else {
                // First time seeing the key
                params[key] = value;
            }
        }
    }

    // Final pass: Convert single string values back to strings if they ended up as arrays of length 1
    for (const key in params) {
        if (Array.isArray(params[key]) && params[key].length === 1) {
            params[key] = params[key][0];
        }
    }

    return params;
}
```

This function handles all specified requirements: removing the optional leading `?`, splitting pairs by `&`, splitting key/value by the first `=`, replacing `+` with spaces, decoding both keys and values using `decodeURIComponent`, assigning an empty string to keys without `=`, and managing single versus multiple occurrences of keys (single string vs. array of strings). It skips any empty pairs resulting from the splitting process.

