function deepMerge(base, override) {
  // Helper to check if a value is a plain object (and not null or array)
  const isPlainObject = (obj) => {
    return typeof obj === 'object' && obj !== null && !Array.isArray(obj) && obj.constructor === Object;
  };

  // Start with a deep clone of the base to ensure immutability
  // We use JSON stringify/parse as a simple deep clone for plain objects
  const result = JSON.parse(JSON.stringify(base));

  if (!isPlainObject(override)) {
    // If override isn't an object, we can't merge properties, return a deep clone of base
    return result;
  }

  for (const key in override) {
    if (Object.hasOwnProperty.call(override, key)) {
      const overrideValue = override[key];
      const baseValue = base[key];

      // 1. Ignore undefined in override
      if (overrideValue === undefined) {
        continue;
      }

      if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
        // 2. Recursively merge plain objects
        result[key] = deepMerge(baseValue, overrideValue);
      } else {
        // 3. Override: If it's not a mergeable object, use the override value.
        // This handles null replacement, arrays being replaced, and primitive replacement.
        // We deep clone the override value itself to ensure the result is completely independent.
        if (typeof overrideValue === 'object' && overrideValue !== null) {
          result[key] = JSON.parse(JSON.stringify(overrideValue));
        } else {
          result[key] = overrideValue;
        }
      }
    }
  }

  return result;
}
```

This function performs a deep merge by first cloning the `base` object entirely to guarantee immutability. It then iterates over the `override` object. If both the base and override values for a key are plain objects, it calls `deepMerge` recursively. Otherwise, it replaces the value in the result with a deep clone of the override value (handling primitives, arrays, and `null` replacement as per requirements), effectively ensuring that changing the returned object will never affect the inputs. `undefined` values in `override` are skipped.

