#include <string>
#include <cctype>
#include <map>
#include <algorithm>

long long parse_duration(const std::string& s) {
    if (s.empty()) {
        return -1;
    }

    long long total_seconds = 0;
    int h_count = 0, m_count = 0, s_count = 0;
    std::string current_unit = "";
    std::string current_number_str = "";

    // Helper lambda to process the completed number and unit
    auto process_part = [&]() -> bool {
        if (current_number_str.empty() || current_unit.empty()) {
            // Should not happen if parsing is done correctly, but safety check
            return false;
        }

        try {
            long long value = std::stoll(current_number_str);
            if (current_unit == "h") {
                h_count++;
                total_seconds += value * 3600;
            } else if (current_unit == "m") {
                m_count++;
                total_seconds += value * 60;
            } else if (current_unit == "s") {
                s_count++;
                total_seconds += value;
            } else {
                // Unknown unit
                return false;
            }
        } catch (const std::invalid_argument&) {
            // Number string was not a valid long long (shouldn't happen based on constraints but good practice)
            return false;
        } catch (const std::out_of_range&) {
            // Number overflow (though constraints say it won't happen)
            return false;
        }

        current_number_str.clear();
        current_unit.clear();
        return true;
    };


    int unit_order = 0; // 0: none, 1: h, 2: m, 3: s

    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];

        if (std::isdigit(c)) {
            // Building the number part
            if (current_unit.empty() && !current_number_str.empty()) {
                 // This state should ideally not be reachable if logic is tight, but guards against spurious transitions
                 return -1; 
            }
            current_number_str += c;

        } else if (c == 'h' || c == 'm' || c == 's') {
            // Unit encountered

            // 1. Check if we have a preceding number
            if (current_number_str.empty()) {
                return -1; // Unit without a number
            }

            // 2. Check for previous units or repetition
            if (!current_unit.empty()) {
                // Found a new unit but current_unit is not empty, meaning we expected the number, not a unit again
                // This implies a structure like "1h2m" where '2' is treated as a new number but we just processed 'h'.
                // If current_unit is not empty, we should have processed the number already.
                return -1; 
            }

            // 3. Check for ordering and repetition
            if (unit_order == 1 && (c == 'm' || c == 's')) return -1; // H followed by M/S is okay, but H followed by H is caught later if we re-evaluate state machine
            if (unit_order == 2 && (c == 'h' || c == 's')) return -1; // M followed by H/S
            if (unit_order == 3 && (c == 'h' || c == 'm')) return -1; // S followed by H/M

            if (current_unit == c) {
                return -1; // Repeated unit
            }

            // Process the previous part (number + unit)
            if (!process_part()) {
                return -1; // Processing failed (e.g., unknown unit, though unit check above handles known units)
            }

            // Reset for the next part
            current_number_str.clear();
            current_unit = std::string(1, c);
            unit_order++;


        } else {
            // Character is not digit or valid unit (space, sign, etc.)
            return -1;
        }
    }

    // After the loop, process any trailing number/unit segment
    if (!current_number_str.empty() && !current_unit.empty()) {
        if (!process_part()) {
            return -1; // Final processing failed
        }
    } else if (!current_number_str.empty() || !current_unit.empty()) {
        // If one is empty but the other isn't (e.g., "12" or "h"), it's invalid
        return -1;
    } else if (s.length() > 0) {
        // String ended, but we didn't successfully process any part (e.g., empty string was caught, but maybe only digits left?)
        // If the string wasn't empty but process_part was never called successfully, it's invalid.
        // Since we check for empty string at start, this means the content was invalid.
        return -1;
    }

    // Final check on order constraints: h, m, s must appear at most once, and in that order.
    // The logic above handles *sequence* and *repetition*. We must ensure we haven't missed constraints.
    // If unit_order > 3, it means we parsed more than 3 distinct units, which implies repetition or invalid units.
    if (unit_order > 3) {
        return -1;
    }

    // Verify that if we parsed any parts, they adhere to the H -> M -> S sequence structure.
    // This check is mostly redundant if the internal logic correctly tracks unit_order, but confirms the constraints.
    if (h_count > 1 || m_count > 1 || s_count > 1) {
        // This catches cases where the parser might allow re-processing due to state errors, though the unit checks should prevent it.
        return -1; 
    }

    return total_seconds;
}
```

The function iterates through the input string, distinguishing between sequences of digits (representing a number) and the unit characters (`h`, `m`, `s`). It uses state tracking to ensure that:
1. Every number is immediately followed by a valid unit.
2. No unit appears more than once.
3. The units strictly follow the sequence: Hours $\rightarrow$ Minutes $\rightarrow$ Seconds.
4. No extraneous characters (like spaces or signs) are present.

If any validation fails during parsing, or if the string is empty, it returns -1. If parsing is successful, it accumulates the total duration in seconds and returns it.

